"""Boulware Bot: the computational / automated-negotiation school. A time-dependent tactic in TOTAL-COST
space (hold firm, concede late), blended with tit-for-tat, AC_next / AC_time acceptance and a simple
opponent model (the supplier's standing total costs per case and supplier).

Knobs: beta (>1 = Boulware, concede late), tft (extra share of the remaining gap when the supplier
conceded more than last round), start (first target vs the opening cost), floor (reservation when there
is no alternative), end (final target vs the opening cost without an alternative).
"""

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..play import closing_move, latest, live_threads, moves_left, standing
from .rational import _first_terms, _message


def target_cost(c0, c_res, has_alt, t, beta=3.0, start=0.88, end=0.97):
    """Our target total cost at time t in [0, 1]: c_start + (c_end - c_start) * t**beta."""
    c_start = start * c0
    c_end = max(c_res * 0.98, c_start) if has_alt else end * c0
    return c_start + (c_end - c_start) * min(max(t, 0.0), 1.0) ** beta


class BoulwareAgent:
    def __init__(self, beta=3.0, tft=0.10, start=0.88, floor=0.90, end=0.97):
        self.beta, self.tft, self.start, self.floor, self.end = beta, tft, start, floor, end
        self._case_id, self._costs = None, {}

    def supplier_costs(self, sid):
        """Opponent model: the supplier's standing total costs, oldest first."""
        return list(self._costs.get(sid, []))

    def concession_rate(self, sid):
        """Mean cost drop per supplier move (0 with fewer than two quotes)."""
        c = self.supplier_costs(sid)
        return (c[0] - c[-1]) / (len(c) - 1) if len(c) > 1 else 0.0

    def decide(self, case, threads):
        try:
            return self._decide(case, threads)
        except Exception:  # never crash a case: close safely (must-haves + alternative), else walk away
            try:
                return closing_move(case, threads)
            except Exception:
                live = live_threads(threads) or list(threads)
                return {"supplier_id": live[0] if live else None, "message": {"action": {"type": "walk_away"}}}

    def _decide(self, case, threads):
        live = live_threads(threads)
        if not live:
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if case.get("case_id") != self._case_id:
            self._case_id, self._costs = case.get("case_id"), {}
        std = {s: standard_terms(threads[s]) for s in live}
        cost = lambda s, t: total_cost(case, t, std[s])  # noqa: E731
        quoting = [s for s in live if standing(threads[s])[1].get("unit_price") is not None]
        if not quoting:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
        for s in quoting:  # opponent model: every sheet the supplier has put on the table
            self._costs[s] = [cost(s, m["term_sheets"][0]["terms"]) for m in threads[s]
                              if m.get("from") != "buyer" and m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        sid = min(quoting, key=lambda s: cost(s, standing(threads[s])[1]))
        events = threads[sid]
        sheet_id, terms = standing(events)
        c_now, c0 = cost(sid, terms), cost(sid, _first_terms(events))
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        has_alt = bool(alt.get("unit_price"))
        reservation = total_cost(case, alt) if has_alt else self.floor * c0
        compliant = must_haves_ok(case, terms, std[sid])
        final_ok = compliant and (c_now < reservation if has_alt else True)
        status, left = latest(events).get("status"), moves_left(case, events)
        accept = {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}

        sent = sum(m.get("from") == "buyer" for m in events)
        t = sent / max(sent + left, 1)
        target = target_cost(c0, reservation, has_alt, t, self.beta, self.start, self.end)
        hist = self._costs[sid]
        if len(hist) >= 3 and hist[-2] - hist[-1] > hist[-3] - hist[-2] and hist[-2] > hist[-1]:
            target += self.tft * (c_now - target)  # tit-for-tat: they moved more, so do we
        target = min(target, c_now)

        def at(p):
            return complete_offer(case, {**terms, "unit_price": p})

        p_hi, p_lo = terms["unit_price"], terms["unit_price"] * 0.5
        c_hi, c_lo = cost(sid, at(p_hi)), cost(sid, at(p_lo))
        price = p_hi if c_hi == c_lo else p_hi + (target - c_hi) * (p_lo - p_hi) / (c_lo - c_hi)
        offer = at(round(min(max(price, p_lo), p_hi), 2))

        if status in {"agreed", "final_offer"} or left <= 0:
            if status == "final_offer" and left > 0 and final_ok and cost(sid, at(p_hi)) < c_now:
                return _message(case, sid, at(p_hi), "We accept your price; please confirm the terms below.")
            return accept if final_ok else {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
        if compliant and c_now <= cost(sid, offer):  # AC_next
            return accept
        if left <= 1 and final_ok:  # AC_time
            return accept
        return _message(case, sid, offer, "Thank you for your offer. Based on our analysis we can offer the terms below.")

from arena_kit.agents.boulware import BoulwareAgent, target_cost
from arena_kit.cost import total_cost

from test_kit import CASE


def _threads(prices, status="open", sent=()):
    ev = []
    for i, p in enumerate(prices):
        ev.append({"from": "sup:A", "status": status if i == len(prices) - 1 else "open",
                   "term_sheets": [{"term_sheet_id": f"o{i}", "terms": {"unit_price": p, "payment_days": 60}}]})
        if i < len(sent):
            ev.append({"from": "buyer", "term_sheets": [{"terms": {"unit_price": sent[i]}}]})
    return {"sup:A": ev}


def _alt(price, **extra):
    return {**CASE, **extra, "buyer": {**CASE["buyer"], "alternative": {"kind": "x", "ref": None, "terms": {"unit_price": price, "payment_days": 60}}}}


def test_target_curve_is_non_increasing_in_firmness_and_bounded():
    ts = [target_cost(1000, 900, True, i / 10) for i in range(11)]
    assert all(a <= b for a, b in zip(ts, ts[1:]))  # concession = target cost rises toward the supplier
    assert ts[1] < 880 + 0.01 * 20 and abs(ts[-1] - 882) < 1e-6  # ~c_start early, c_end = 0.98*900 late
    assert abs(target_cost(1000, 0, False, 1.0) - 970) < 1e-6


def test_offer_never_above_supplier_price():
    msg = BoulwareAgent().decide(_alt(36.0), _threads([44.0, 43.0], "open", [38.0]))["message"]
    assert msg["term_sheets"][0]["terms"]["unit_price"] <= 43.0
    assert set(msg["term_sheets"][0]["terms"]) == {"unit_price", "payment_days"} and "alternative" not in msg["body"]


def test_ac_next_accepts_cheap_standing_sheet():
    msg = BoulwareAgent().decide(CASE, _threads([44.0, 30.0], "open", [38.0]))["message"]
    assert msg["action"] == {"type": "accept", "term_sheet_id": "o1"}


def test_never_accepts_worse_than_reservation():
    case = _alt(36.0)
    assert total_cost(case, {"unit_price": 40.0, "payment_days": 60}) > total_cost(case, case["buyer"]["alternative"]["terms"])
    for status in ("final_offer", "agreed"):
        assert BoulwareAgent().decide(case, _threads([44.0, 40.0], status, [38.0]))["message"]["action"] == {"type": "walk_away"}
    last = {**case, "round_limit": 1}
    assert BoulwareAgent().decide(last, _threads([44.0, 40.0], "open", [38.0]))["message"]["action"] == {"type": "walk_away"}


def test_final_offer_counter_at_their_price_on_our_terms(monkeypatch):
    monkeypatch.setattr("arena_kit.agents.boulware.standard_terms", lambda ev: {"payment_days": 14})
    th = _threads([44.0, 40.0], "final_offer", [38.0])
    del th["sup:A"][-1]["term_sheets"][0]["terms"]["payment_days"]  # price-only sheet: closes on their 14 days
    msg = BoulwareAgent().decide(_alt(60.0), th)["message"]
    assert msg["term_sheets"][0]["terms"] == {"unit_price": 40.0, "payment_days": 60}
    monkeypatch.setattr("arena_kit.agents.boulware.standard_terms", lambda ev: {})
    assert BoulwareAgent().decide(_alt(60.0), th)["message"]["action"]["type"] == "accept"  # nothing to gain


def test_tit_for_tat_extra_concession_only_when_supplier_moved_more():
    case = _alt(60.0)
    price = lambda prices: BoulwareAgent().decide(case, _threads(prices, "open", [30.0, 31.0]))["message"]["term_sheets"][0]["terms"]["unit_price"]
    bigger = price([50.0, 49.0, 46.0])  # moved 1 then 3
    stalled = price([50.0, 49.0, 49.0])  # moved 1 then 0 (same standing price as the next call)
    same = price([50.0, 47.0, 46.0])  # moved 3 then 1: no extra
    assert bigger / 46.0 > same / 46.0  # the extra concession lifts our offer relative to their price
    assert stalled <= 49.0


def test_opponent_model_and_reset_on_new_case():
    a = BoulwareAgent()
    a.decide(CASE, _threads([44.0, 42.0, 41.0], "open", [38.0, 39.0]))
    assert len(a.supplier_costs("sup:A")) == 3 and a.concession_rate("sup:A") > 0
    a.decide({**CASE, "case_id": "case:T02"}, _threads([44.0]))
    assert len(a.supplier_costs("sup:A")) == 1


def test_no_live_threads_does_not_crash():
    ended = {"sup:A": [{"from": "sup:A", "status": "walked_away", "term_sheets": []}]}
    assert BoulwareAgent().decide(CASE, ended)["message"]["action"] == {"type": "walk_away"}
    assert BoulwareAgent().decide(CASE, {})["supplier_id"] is None


def test_crash_falls_back_safely(monkeypatch):
    def boom(*a, **k):
        raise RuntimeError("boom")

    monkeypatch.setattr(BoulwareAgent, "_decide", boom)
    assert BoulwareAgent().decide(_alt(36.0), _threads([44.0, 40.0]))["message"]["action"] == {"type": "walk_away"}
    assert BoulwareAgent().decide(_alt(60.0), _threads([44.0, 40.0]))["message"]["action"]["type"] in {"accept", "walk_away"}

